import { BulletChart, type BulletMeasure } from '@absoluteui/components/bullet-chart';

const host = document.querySelector<HTMLElement>('#sla');
if (host) {
  const measures: BulletMeasure[] = [
    { id: 'uptime', label: 'Uptime', value: 0.994, target: 0.999, ranges: [0.99, 0.995, 1] },
    { id: 'first-response', label: 'First response in 1 h', value: 0.87, target: 0.9, ranges: [0.8, 0.9, 1] },
  ];
  const chart = BulletChart.create(host, {
    label: 'Service levels',
    measures,
    rangeLabels: ['Breach', 'At risk', 'Met'],
    valueFormat: { style: 'percent', maximumFractionDigits: 1 },
    valueAxis: { min: 0.75, max: 1 },
    color: 2,
  });
  chart.update({ measures: measures.map((m) => (m.id === 'uptime' ? { ...m, value: 0.9991 } : m)) });
}
